using UnityEngine;using Codice.Bosses;using Codice.Characters;using System;using System.Reflection;
public static class TelegraphProbe{const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;public static string Run(){var go=new GameObject("Telegraph test");go.SetActive(false);var b=go.AddComponent<BossCharacter>();int passed=0;Action<string,object> set=(key,v)=>typeof(BossCharacter).GetField(key,F).SetValue(b,v);Action<string> call=key=>typeof(BossCharacter).GetMethod(key,F).Invoke(b,null);try{go.transform.position=new Vector3(4000,0,4000);set("facing",Vector3.forward);set("aim",go.transform.position+Vector3.forward*8);foreach(var attack in new[]{BossAttack.Sweep,BossAttack.Slam,BossAttack.Mud,BossAttack.Rock,BossAttack.Bow}){set("<CurrentAttack>k__BackingField",attack);call("ShowStandardTelegraph");var w=(GameObject)typeof(BossCharacter).GetField("standardWarning",F).GetValue(b);if(!w||w.GetComponentsInChildren<LineRenderer>().Length==0)throw new Exception("Missing "+attack);call("ClearStandardTelegraph");if(w.activeSelf)throw new Exception("Warning persists");passed++;}foreach(var kind in new[]{BossKind.SpearWarden,BossKind.TwinBladeWarden,BossKind.StoneGuardian}){b.kind=kind;set("<CurrentAttack>k__BackingField",BossAttack.Sweep);call("ShowWardenTelegraph");var w=(GameObject)typeof(BossCharacter).GetField("wardenWarning",F).GetValue(b);var line=w.GetComponent<LineRenderer>();float radius=Vector3.Distance(line.GetPosition(0),line.GetPosition(1));if(Mathf.Abs(radius-(kind==BossKind.SpearWarden?3.5f:3.2f))>.01f)throw new Exception("Wrong radius");passed++;}return passed+" telegraph checks passed";}finally{UnityEngine.Object.DestroyImmediate(go);}}}
